/* Ensures that faction-restricted items include goblins */
UPDATE `item_template` SET `allowablerace` = `allowablerace` | @GoblinMask WHERE `allowablerace` & @OrcMask AND `allowablerace` != -1 AND `allowablerace` != 2147483647 AND `allowablerace` != 2047 AND `allowablerace` != 4095 AND `allowablerace` != 16383 AND `allowablerace` != 32767 AND `allowablerace` != 65535 AND `allowablerace` != 131071 AND `allowablerace` != 262143 AND `allowablerace` != 524287 AND `allowablerace` != 1048575 AND `allowablerace` != 2097151;

/* Add racial mount items */
DELETE FROM `item_template` WHERE `entry` IN (@GoblinMount1Item, @GoblinMount2Item);

/* Add Cataclysm starting equipment for goblins */
DELETE FROM `item_template` WHERE  `entry` IN (
    @GoblinBrawlersGreavesItem, @GoblinBrawlersHarnessItem, @GoblinBrawlersBootsItem, @GoblinBrawlersGauntletsItem,
    @GoblinTrappersShirtItem, @GoblinTrappersPantsItem, @GoblinTrappersBootsItem,
    @WornWoodChopperItem,
    @GoblinThugsTunicItem, @GoblinThugsPantsItem, @GoblinThugsBootsItem,
    @GoblinNeophytesRobeItem, @GoblinNeophytesPantsItem, @GoblinNeophytesShoesItem,
    @PrimalShirtItem, @PrimalPantsItem, @PrimalBootsItem,
    @GoblinApprenticesRobeItem, @GoblinApprenticesPantsItem, @GoblinApprenticesBootsItem,
    @GoblinAcolytesRobeItem, @GoblinAcolytesPantsItem, @GoblinAcolytesShoesItem
);
